// Enumerate sorted four-row multisets over a legal 15-core. Output core index and support masks. Blue k-sets must not be jointly missed by 7-k rows.
use std::io::{self,BufRead};
fn main(){let target=std::env::args().nth(1).map(|s|s.parse::<u32>().unwrap()).unwrap_or(47);let maxroot=std::env::args().any(|s|s=="--maxroot");for(idx,line)in io::stdin().lock().lines().enumerate(){let a:Vec<u32>=line.unwrap().split_whitespace().map(|s|s.parse().unwrap()).collect();assert_eq!(a.len(),15);let budget=target-4-a.iter().map(|x|x.count_ones()).sum::<u32>()/2;let mut sets=vec![0u32];for(i,x)in a.iter().enumerate(){for j in 0..sets.len(){if sets[j]&x==0{sets.push(sets[j]|1<<i)}}}let s:Vec<_>=sets.iter().copied().filter(|x|(3..=budget-9).contains(&x.count_ones())).collect();let mut miss=vec![vec![vec![];s.len()];3];for z in 3..=5{let q:Vec<_>=sets.iter().filter(|x|x.count_ones()==z).collect();for(i,t)in s.iter().enumerate(){let mut m=vec![0u64;(q.len()+63)/64];for(j,&&x)in q.iter().enumerate(){if x&t==0{m[j/64]|=1<<(j%64)}}miss[(z-3)as usize][i]=m}}
let mut adj=vec![vec![];s.len()];for i in 0..s.len(){for j in i..s.len(){if (s[i].count_ones()+s[j].count_ones()<=budget-6)&&miss[2][i].iter().zip(&miss[2][j]).all(|(x,y)|x&y==0){adj[i].push(j)}}}
for i in 0..s.len(){for &j in &adj[i]{let both:Vec<_>=adj[j].iter().copied().filter(|k|adj[i].binary_search(k).is_ok()).collect();for (pos,&k) in both.iter().enumerate(){let v=&miss[1];if (0..v[i].len()).any(|t|v[i][t]&v[j][t]&v[k][t]!=0){continue}for &l in &both[pos..]{let rows=[s[i],s[j],s[k],s[l]];if rows.iter().map(|x|x.count_ones()).sum::<u32>()!=budget||adj[k].binary_search(&l).is_err(){continue}if (0..v[l].len()).any(|t|v[l][t]&((v[i][t]&v[j][t])|((v[i][t]|v[j][t])&v[k][t]))!=0){continue}let u=&miss[0];if (0..u[l].len()).any(|t|u[l][t]&u[k][t]&u[j][t]&u[i][t]!=0){continue}if (0..15).any(|t|a[t].count_ones()+(rows.iter().filter(|x|*x&(1<<t)!=0).count() as u32)<4){continue}if maxroot {let mut g=[0u32;20];g[..15].copy_from_slice(&a);g[19]=15<<15;for(h,&s)in rows.iter().enumerate(){g[15+h]=s|1<<19;let mut x=s;while x!=0{g[x.trailing_zeros() as usize]|=1<<(15+h);x&=x-1;}}let current=budget+4;if g.iter().any(|&s|{if s.count_ones()!=4{return false} let mut x=s;let mut sum=0;while x!=0{sum+=g[x.trailing_zeros() as usize].count_ones();x&=x-1;}sum<current}){continue}}println!("{} {} {} {} {}",idx,s[i],s[j],s[k],s[l]);}}}}}}
